import{_ as a,o as i,c as t,a6 as n}from"./chunks/framework.DL_pga9_.js";const u=JSON.parse('{"title":"Constant Generic Parameters","description":"","frontmatter":{},"headers":[],"relativePath":"design/archive/constant_generic_parameters.md","filePath":"design/archive/constant_generic_parameters.md","lastUpdated":1780030916000}'),s={name:"design/archive/constant_generic_parameters.md"};function r(l,e,c,o,d,p){return i(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="constant-generic-parameters" tabindex="-1">Constant Generic Parameters <a class="header-anchor" href="#constant-generic-parameters" aria-label="Permalink to “Constant Generic Parameters”">​</a></h1><h2 id="order" tabindex="-1">Order <a class="header-anchor" href="#order" aria-label="Permalink to “Order”">​</a></h2><p>Recommended Issue order: 3.</p><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to “Goal”">​</a></h2><p>Add scalar compile-time values as generic parameters, separate from type parameters.</p><p>Example direction:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>type Array&lt;T, const N: u32&gt; = native;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>fun repeat&lt;const N: u32&gt;(value: i32) -&gt; Array&lt;i32, N&gt; = native;</span></span></code></pre></div><p>Current surface direction:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>val fixed: array&lt;i32, 4&gt; = [1, 2, 3, 4];</span></span>
<span class="line"><span>val dynamic: vector&lt;i32&gt; = [1, 2, 3];</span></span>
<span class="line"><span></span></span>
<span class="line"><span>fun view(xs: span&lt;i32&gt;) -&gt; u32 = native;</span></span></code></pre></div><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to “Dependencies”">​</a></h2><p>Prerequisites:</p><ul><li>Existing enhanced generics, specialization, and mangling.</li><li><a href="./generalized_delete">Generalized <code>= delete</code> Declarations</a> is recommended first so invalid const-generic specializations can use one consistent negative declaration mechanism.</li></ul><p>Unblocks:</p><ul><li><a href="./const_fun"><code>const fun</code> And Compile-Time Computation</a></li><li><a href="./../enhanced_tuples">Enhanced Tuple Types</a>, for <code>tuple_element&lt;T, I&gt;</code> and tuple slice bounds.</li><li>Stable <code>.ngo</code> symbol persistence in <a href="./bytecode_module_loading">Bytecode Module Loading</a>.</li></ul><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to “Scope”">​</a></h2><p>In scope:</p><ul><li>Syntax for const generic parameters.</li><li>Supported scalar types: initially <code>bool</code>, signed/unsigned integers, and possibly <code>string</code> only if needed.</li><li>Type checker representation for const generic arguments.</li><li>Monomorphization keys and name mangling including const values.</li><li>Validation that const generic arguments are compile-time constants.</li><li>Use in type aliases, native opaque types, functions, and constraints.</li><li>Fixed-size <code>array&lt;T, N&gt;</code> type annotation backed by const generic <code>N</code>.</li><li>Dynamic owning <code>vector&lt;T&gt;</code> type annotation.</li><li>Non-owning contiguous <code>span&lt;T&gt;</code> type annotation for native/runtime APIs.</li></ul><p>Out of scope:</p><ul><li>Full <code>const fun</code>.</li><li>Arbitrary compile-time expressions beyond already-supported scalar const values.</li><li>Runtime generic metadata in ORGASM.</li></ul><h2 id="acceptance-criteria" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to “Acceptance Criteria”">​</a></h2><ul><li>Parser accepts <code>fun&lt;const N: u32&gt;()</code>.</li><li>Parser accepts mixed parameters like <code>type Buffer&lt;T, const N: u32&gt; = native;</code>.</li><li>Type checker rejects non-constant values as const generic arguments.</li><li><code>Buffer&lt;i32, 4&gt;</code> and <code>Buffer&lt;i32, 8&gt;</code> are distinct instantiated types.</li><li>ORGASM symbols are fully monomorphized and include const generic values in mangling.</li></ul><h2 id="array-vector-and-span-model" tabindex="-1">Array, Vector, And Span Model <a class="header-anchor" href="#array-vector-and-span-model" aria-label="Permalink to “Array, Vector, And Span Model”">​</a></h2><p>The collection type split is:</p><ul><li><code>array&lt;T, N&gt;</code> is a fixed-size owning value with compile-time length <code>N</code>.</li><li><code>vector&lt;T&gt;</code> is the dynamic owning contiguous container and replaces the previous dynamic <code>array&lt;T&gt;</code> meaning.</li><li><code>span&lt;T&gt;</code> is a non-owning contiguous view. It can be used in type signatures before the runtime exposes general extraction/conversion APIs.</li></ul><p>Compatibility migration:</p><ul><li><code>[T]</code> type annotation is treated as <code>vector&lt;T&gt;</code>.</li><li>Suffix syntax is purely generic sugar: <code>T vector</code> is <code>vector&lt;T&gt;</code>, and <code>T array</code> is <code>array&lt;T&gt;</code>.</li><li><code>array&lt;T&gt;</code> is rejected; callers must write <code>array&lt;T, N&gt;</code> for fixed arrays or <code>vector&lt;T&gt;</code> / <code>T vector</code> for dynamic vectors.</li><li>Array literals remain runtime array cells today, but type-check as <code>vector&lt;T&gt;</code> unless an expected fixed <code>array&lt;T, N&gt;</code> type is present.</li></ul><p>Implemented behavior in this stage:</p><ul><li>Parser accepts <code>const N: u32</code> generic parameters and scalar literal generic arguments.</li><li>Type checker represents scalar const generic arguments as <code>ConstValueType</code>.</li><li>Generic type/function instantiation validates type-vs-const parameter positions.</li><li>Fixed <code>array&lt;T, N&gt;</code> checks array literal length when an expected fixed array type exists.</li><li>Mangling/canonical names include const values as explicit <code>const&lt;type:value&gt;</code> segments.</li></ul><p>Deferred runtime/API work:</p><ul><li>Runtime storage currently continues to use existing array cells for both fixed array literals and vector literals.</li><li>Dedicated vector/span runtime layouts and conversions are separate follow-up work.</li><li><code>span&lt;T&gt;</code> is type-checkable but construction/extraction APIs still need standard library/runtime design.</li></ul>`,30)])])}const m=a(s,[["render",r]]);export{u as __pageData,m as default};
